insert into public.inspection_jurisdictions (code, name, sort_order, scheduling_method, portal_url, phone, cutoff_minutes, cutoff_label, inspection_hours, notes, verified_on) values
  ('SCOT', 'City of Scottsdale', 1, 'Scottsdale SPUR portal for permits started after Jan 6, 2026 (permit → Inspections → Request Inspection). Older permits: legacy eServices with the permit-receipt keycode and the code from the Inspection Code Lookup, or the QR code on the permit card.', null, '480-312-5750', null, 'Pick the date in SPUR', 'Apr–Oct 6:00 AM–2:30 PM · Nov–Mar 7:00 AM–3:30 PM', 'Fire & life safety: 480-312-1855. Call the area inspector the morning of for an ETA (6:00–6:30 AM Apr–Oct, 7:00–7:30 AM Nov–Mar).', '2026-11-09'),
  ('PHX', 'City of Phoenix', 2, 'IVR (602) 495-0800 (permit number, address, inspection type; stay on for the confirmation number) or online with the permit number + Web Inspection Key, up to 5 inspections per request on one permit. New residential applications use SHAPE PHX.', null, '602-495-0800', 1260, '9:00 PM (Mon–Fri) for the next workday', null, 'Overflow carryovers are auto-rescheduled to the next working day with priority. Remote video inspections available for many home projects.', '2026-11-09'),
  ('PV', 'Town of Paradise Valley', 3, 'Accela Citizen Access portal or by text per the Town inspection list. A confirmation number is required: no number, not scheduled.', 'https://aca-prod.accela.com/PARADISEVLY', '480-348-3692', 900, '3:00 PM for the next business day', 'Oct–Apr 7:00 AM–3:00 PM · May–Sep 6:00 AM–3:00 PM', 'Ladder for grout inspections 8 ft and higher and for roof nailing / shear. ROW permits need a pre-con with Engineering (480-348-3681).', '2026-11-09'),
  ('MESA', 'City of Mesa', 4, 'DIMES (Accela) online; text 480-644-2428 "S PMT-XXXX Code MM/DD/YYYY" (RS = reschedule, C = cancel); or the 24-hour phone line.', null, '480-644-2428', null, 'Next business day (exact cutoff to confirm)', 'Mon–Fri 6:30 AM–5:00 PM', 'Results emailed from noreply@mesaaz.gov. Meter set after final: 480-644-2221. Permit void if no inspection within 180 days.', '2026-11-09'),
  ('TMP', 'City of Tempe', 5, '24-hour IVR or the Citizen Access Portal; up to two weeks ahead, only after the permit is issued and work has started.', null, '480-350-8341', 1440, 'Midnight for the next business day', '6:30 AM–3:30 PM business days', 'ETA line 480-350-8341, call 6:00–6:30 AM the morning of.', '2026-11-09'),
  ('CHD', 'City of Chandler', 6, 'Text 844-281-3520 "S [permit #] [code] [date]" (C = cancel, RESCHED, RESULT); IVR 480-782-3100; or Accela online.', 'https://aca-prod.accela.com/CHANDLER', '480-782-3000', null, 'Not published (confirm with Development Services)', null, null, '2026-11-09'),
  ('CC', 'Town of Cave Creek', 7, 'By phone; the Town also runs an online Citizen Portal (iWorQ). Confirm online scheduling with the Town.', null, '480-488-1400', null, 'Not published (confirm with the Town)', null, 'Fire sprinklers: Rural Metro (schedule separately). Septic: Maricopa County Environmental Services. Both approvals needed before final.', '2026-11-09'),
  ('CF', 'Town of Carefree', 8, 'Town SmartGov portal; scheduling method not published (confirm with the Building Department).', 'https://twn-carefree-az.smartgovcommunity.com', '480-488-3686', null, 'Not published (confirm with the Building Department)', null, 'Surveyor and engineer certifications: pre-grading fence as-built, setbacks and finished floor before the pour, height at framing, engineer''s completion letter. Rural Metro and County septic approvals before final.', '2026-11-09'),
  ('MCO', 'Maricopa County (unincorporated)', 9, 'Permit Center portal: permit → Inspections tab → check the inspection → Request Inspection → date → on-site contact and gate code in Comments. Prerequisites are enforced in the portal.', null, '602-506-7170', 930, '3:30 PM (online) for the next business day', null, 'Two tracks: Final Drainage (Engineering) must pass before Building Final, not the same day. Call Center 602-506-3301.', '2026-11-09')
